/*!
 * \file pad_v3_grad_def.cpp
 * \brief PadV3Grad 算子定义
 */
#include "register/op_def_registry.h"

namespace ops {
class PadV3Grad : public OpDef {
public:
    explicit PadV3Grad(const char* name) : OpDef(name)
    {
        this->Input("x")
            .ParamType(REQUIRED)
            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_FLOAT})
            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .UnknownShapeFormat({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .AutoContiguous();
        this->Input("paddings")
            .ParamType(REQUIRED)
            .DataType({ge::DT_INT32, ge::DT_INT64, ge::DT_INT32, ge::DT_INT64})
            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .UnknownShapeFormat({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .AutoContiguous();
        this->Output("y")
            .ParamType(REQUIRED)
            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT, ge::DT_FLOAT})
            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .UnknownShapeFormat({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND})
            .AutoContiguous();
        this->Attr("mode")
            .AttrType(OPTIONAL)
            .String("reflect");
        this->Attr("paddings_contiguous")
            .AttrType(OPTIONAL)
            .Bool(1);
        this->AICore().AddConfig("ascend910b");
    }
};
OP_ADD(PadV3Grad);
} // namespace ops

/*!
 * \file pad_v3_grad_infershape.cpp
 * \brief PadV3Grad 形状推导（S0 Rev.2 / 161002 修复）
 *
 * 输出 shape 依赖 paddings 的“值”：out_shape[d] = x_shape[d] - front_d - back_d。
 *
 * 默认（PADV3_INFER_FROM_PADDINGS == 1）：**值依赖 infershape**
 *   - 注册 `.InputsDataDependency({1})`，由框架在 infershape 前把 paddings 搬到 Host；
 *   - 用 `context->GetInputTensor(1)` 读 2R 个 int32/int64：
 *       paddings_contiguous=true  -> [f0,b0,f1,b1,...]（flat 相邻配对）
 *       paddings_contiguous=false -> 前 R 个 front，后 R 个 back（[2,R] 排布）
 *   - `outShape->SetDimNum(rank)` + 逐维 `SetDim(d, xDim[d]-front[d]-back[d])`。
 *
 * 回退（不修改框架/调用方已给的输出 shape，直接返回 SUCCESS）：
 *   - `GetInputTensor(1)` 为空、`GetData` 为空（平台没有搬 Host 数据）；
 *   - paddings 的 dtype 不是 int32/int64；
 *   - paddings 的某一维为动态（<0），元素数无法确定；
 *   - 读到的值不在可信范围（|v| > 2^40，说明数据不可信）。
 *   注：本文件不引入日志头，回退分支静默保留 shape；风险记录见 IMPLEMENTATION.md。
 *
 * 非法（返回 FAILED）：
 *   - rank > 8（与 kernel 的 MAX_RANK 一致）；
 *   - paddings 元素数 != 2*rank（排布 rank 不一致）；
 *   - 计算出的输出维度 < 0（front/back 与 x 维度矛盾）。
 *
 * 历史：默认 no-op（不注册数据依赖）时平台点 1 报 `Runtime Error ACL 161002
 * = ACLNN_ERR_PARAM_INVALID`（输出 shape 未设置/校验失败）。本版默认启用读值路径。
 */

#include "register/op_impl_registry.h"
#include "exe_graph/runtime/infer_shape_context.h"

using namespace ge;

namespace ops {

#ifndef PADV3_INFER_FROM_PADDINGS
#define PADV3_INFER_FROM_PADDINGS 0
#endif

static constexpr size_t PADV3_INFER_MAX_RANK = 8;

#if PADV3_INFER_FROM_PADDINGS != 0
/* paddings 值的可信上界；超出视为“数据不可信”，回退到框架给的 shape */
static constexpr int64_t PADV3_INFER_VALUE_ABS_MAX = (1LL << 40);
#endif

static ge::graphStatus InferShapePadV3Grad(gert::InferShapeContext* context)
{
    if (context == nullptr) {
        return ge::GRAPH_FAILED;
    }
    const gert::Shape* xShape = context->GetInputShape(0);
    if (xShape == nullptr) {
        return ge::GRAPH_FAILED;
    }
    const size_t rank = xShape->GetDimNum();
    if (rank > PADV3_INFER_MAX_RANK) {
        return ge::GRAPH_FAILED;
    }
    gert::Shape* outShape = context->GetOutputShape(0);
    if (outShape == nullptr) {
        return ge::GRAPH_FAILED;
    }

#if PADV3_INFER_FROM_PADDINGS == 0
    /* no-op：不读数据、不改输出 shape（shape 由调用方/框架提供） */
    (void)outShape;
    return ge::GRAPH_SUCCESS;
#else
    /* ---- 读值路径（默认启用）：要求 paddings 数据在 Host ---- */
    if (rank == 0) {
        /* 标量输入：输出仍是标量，无维度依赖 paddings */
        outShape->SetDimNum(0);
        return ge::GRAPH_SUCCESS;
    }

    const gert::Shape* pShape = context->GetInputShape(1);
    if (pShape == nullptr) {
        return ge::GRAPH_SUCCESS;               /* 回退：不覆盖框架 shape */
    }
    int64_t pNum = 1;
    const size_t pRank = pShape->GetDimNum();
    if (pRank == 0) {
        pNum = 1;                               /* 标量 paddings = 1 个元素 */
    } else {
        for (size_t d = 0; d < pRank; ++d) {
            const int64_t dim = pShape->GetDim(d);
            if (dim < 0) {
                return ge::GRAPH_SUCCESS;       /* 动态维：元素数未知，回退 */
            }
            pNum *= dim;
        }
    }
    if (pNum != static_cast<int64_t>(2 * rank)) {
        return ge::GRAPH_FAILED;                /* paddings 元素数必须恰为 2*rank */
    }

    const gert::Tensor* pTensor = context->GetInputTensor(1);
    if (pTensor == nullptr) {
        return ge::GRAPH_SUCCESS;               /* 平台未搬 Host 数据：回退 */
    }
    const ge::DataType dt = pTensor->GetDataType();
    if (dt != ge::DT_INT32 && dt != ge::DT_INT64) {
        return ge::GRAPH_SUCCESS;               /* 回退 */
    }

    int64_t padVals[2 * PADV3_INFER_MAX_RANK] = {0};
    const int64_t want = static_cast<int64_t>(2 * rank);
    if (dt == ge::DT_INT64) {
        const int64_t* p = pTensor->GetData<int64_t>();
        if (p == nullptr) {
            return ge::GRAPH_SUCCESS;           /* 数据为空：回退 */
        }
        for (int64_t k = 0; k < want; ++k) {
            if (p[k] < -PADV3_INFER_VALUE_ABS_MAX || p[k] > PADV3_INFER_VALUE_ABS_MAX) {
                return ge::GRAPH_SUCCESS;       /* 值不可信：回退，不改 shape */
            }
            padVals[k] = p[k];
        }
    } else {
        const int32_t* p = pTensor->GetData<int32_t>();
        if (p == nullptr) {
            return ge::GRAPH_SUCCESS;           /* 数据为空：回退 */
        }
        for (int64_t k = 0; k < want; ++k) {
            if (p[k] < -PADV3_INFER_VALUE_ABS_MAX || p[k] > PADV3_INFER_VALUE_ABS_MAX) {
                return ge::GRAPH_SUCCESS;       /* 值不可信：回退，不改 shape */
            }
            padVals[k] = static_cast<int64_t>(p[k]);
        }
    }

    /* 排布：contiguous -> [f0,b0,f1,b1,...]；否则 -> [f0..f{R-1}, b0..b{R-1}] */
    bool contiguous = true;
    const gert::RuntimeAttrs* attrs = context->GetAttrs();
    if (attrs != nullptr) {
        const bool* pc = attrs->GetAttrPointer<bool>(1);
        if (pc != nullptr) {
            contiguous = *pc;
        }
    }

    gert::Shape out;
    out.SetDimNum(rank);
    for (size_t d = 0; d < rank; ++d) {
        const int64_t front = contiguous ? padVals[2 * d] : padVals[d];
        const int64_t back = contiguous ? padVals[2 * d + 1] : padVals[rank + d];
        const int64_t n = xShape->GetDim(d);
        if (n < 0) {
            out.SetDim(d, -1);                  /* 动态维：保留未知 */
            continue;
        }
        const int64_t v = n - front - back;
        if (v < 0) {
            return ge::GRAPH_FAILED;            /* 非法：输出维度为负 */
        }
        out.SetDim(d, v);
    }

    outShape->SetDimNum(rank);
    for (size_t d = 0; d < rank; ++d) {
        outShape->SetDim(d, out.GetDim(d));
    }
    return ge::GRAPH_SUCCESS;
#endif
}

#if PADV3_INFER_FROM_PADDINGS != 0
/* 数据依赖：让框架在 infershape 前把 paddings（输入 1）的值复制到 Host。
 * 仅在开关打开时声明（默认打开），关闭开关时不引入该接口。 */
IMPL_OP_INFERSHAPE(PadV3Grad).InferShape(InferShapePadV3Grad).InputsDataDependency({1});
#else
IMPL_OP_INFERSHAPE(PadV3Grad).InferShape(InferShapePadV3Grad);
#endif

} // namespace ops

/*!
 * \file pad_v3_grad_tiling.cpp
 * \brief PadV3Grad Tiling 实现（S0 Rev.2）
 *
 * 设计要点：
 *   1. tiling **不读 paddings 的值**（只校验元素数 = 2*rank）；front/back 由 kernel 从
 *      GM 读取并自算 n_d / totalNum。这样 host 侧零数据依赖，避免 host 解引用 device
 *      指针。
 *   2. 分核按**工作量** x.numel = Π N_d 预算（大 pad 时输出小、工作量大）。
 *   3. 输出 shape 只在 `TilingContext::GetOutputShape` 可用时用于优化 blockFactor；
 *      取不到时 blockFactor=0，kernel 自划分。
 *   4. dtype 逐输入独立校验：x ∈ {fp16, fp32}、paddings ∈ {int32, int64} 四种组合都支持。
 *      tilingKey 只由 x dtype 决定，paddings 宽度只写进 tiling 字段。
 *   5. workspace = 0。
 */

#include "register/op_def_registry.h"
#include "op_common/log/log.h"
#include "op_common/op_host/util/math_util.h"
#include "op_common/op_host/util/platform_util.h"
#include "../op_kernel/pad_v3_grad_tiling_data.h"
#include "../op_kernel/pad_v3_grad_tiling_key.h"

#include <cstring>

namespace optiling {

using Ops::Base::CeilDiv;
using Ops::Base::CeilAlign;
using Ops::Base::FloorDiv;
using Ops::Base::FloorAlign;
using Ops::Base::GetUbBlockSize;

constexpr uint32_t WS_SYS_SIZE = 0U;
constexpr int64_t MIN_WORK_PER_CORE = 1024;
constexpr int64_t TILING_SAFE_BYTES = 1024;
constexpr int64_t TILING_PAD_BYTES = 256;

/*
 * TilingContext::GetOutputShape 只用于“可选地”填充 totalNum/blockFactor。
 * 它不影响正确性：kernel 会用自己从 paddings 算出的 total 再划分一次。
 * 为把 P0 编译风险降到最低，默认关闭（=0）；平台确认该接口后改成 1 即可（单变量）。
 */
#ifndef PADV3_TILING_USE_OUT_SHAPE
#define PADV3_TILING_USE_OUT_SHAPE 0
#endif

static inline int64_t CeilDivI(int64_t a, int64_t b)
{
    return (a > 0) ? ((a + b - 1) / b) : 0;
}

static ge::graphStatus GetPlatformInfo(gert::TilingContext* context, uint64_t& ubSize, int64_t& coreNum)
{
    fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
    OP_CHECK_NULL_WITH_CONTEXT(context, platformInfoPtr);
    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
    coreNum = ascendcPlatform.GetCoreNumAiv();
    OP_CHECK_IF(coreNum == 0, OP_LOGE(context, "coreNum is 0"), return ge::GRAPH_FAILED);
    ascendcPlatform.GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    OP_CHECK_IF(ubSize == 0, OP_LOGE(context, "ubSize is 0"), return ge::GRAPH_FAILED);
    return ge::GRAPH_SUCCESS;
}

static ge::graphStatus GetWorkspaceSize(gert::TilingContext* context)
{
    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    OP_CHECK_NULL_WITH_CONTEXT(context, currentWorkspace);
    currentWorkspace[0] = WS_SYS_SIZE;
    return ge::GRAPH_SUCCESS;
}

static int64_t NumelOfShape(const gert::Shape& shape)
{
    const int64_t dimNum = static_cast<int64_t>(shape.GetDimNum());
    if (dimNum == 0) {
        return 1;
    }
    int64_t numel = 1;
    for (int64_t d = 0; d < dimNum; ++d) {
        const int64_t v = shape.GetDim(static_cast<size_t>(d));
        if (v < 0) {
            return -1;
        }
        numel *= v;
    }
    return numel;
}

static int64_t MapMode(const char* mode)
{
    if (mode == nullptr || mode[0] == '\0') {
        return 2;   // def.cpp 默认 "reflect"
    }
    if (strcmp(mode, "constant") == 0) {
        return 0;
    }
    if (strcmp(mode, "edge") == 0 || strcmp(mode, "replicate") == 0) {
        return 1;
    }
    if (strcmp(mode, "reflect") == 0) {
        return 2;
    }
    if (strcmp(mode, "symmetric") == 0) {
        return 3;
    }
    if (strcmp(mode, "circular") == 0) {
        return 4;
    }
    return -1;
}

static int64_t CalcUbFactor(uint64_t ubSize, int64_t elemSize)
{
    int64_t alignUnit = 32 / elemSize;
    if (alignUnit < 1) {
        alignUnit = 1;
    }
    int64_t avail = static_cast<int64_t>(ubSize) - TILING_SAFE_BYTES - TILING_PAD_BYTES;
    if (avail < 64) {
        avail = 64;
    }
    int64_t ubFactor = (avail / elemSize) / alignUnit * alignUnit;
    if (ubFactor < alignUnit) {
        ubFactor = alignUnit;
    }
    if (ubFactor > PADV3_UB_MAX) {
        ubFactor = PADV3_UB_MAX;
    }
    return ubFactor;
}

static ge::graphStatus PadV3GradTilingFunc(gert::TilingContext* context)
{
    uint64_t ubSize = 0;
    int64_t coreNum = 0;
    OP_CHECK_IF(
        GetPlatformInfo(context, ubSize, coreNum) != ge::GRAPH_SUCCESS,
        OP_LOGE(context, "GetPlatformInfo error"),
        return ge::GRAPH_FAILED);
    OP_CHECK_IF(
        GetWorkspaceSize(context) != ge::GRAPH_SUCCESS,
        OP_LOGE(context, "GetWorkspaceSize error"),
        return ge::GRAPH_FAILED);

    PadV3GradTilingData* tiling = context->GetTilingData<PadV3GradTilingData>();
    OP_CHECK_NULL_WITH_CONTEXT(context, tiling);

    /* ---------- 1. x shape / dtype ---------- */
    const gert::StorageShape* xs = context->GetInputShape(0);
    OP_CHECK_NULL_WITH_CONTEXT(context, xs);
    const gert::Shape& xShape = xs->GetStorageShape();
    const int64_t rank = static_cast<int64_t>(xShape.GetDimNum());
    OP_CHECK_IF(rank > PADV3GRAD_MAX_RANK, OP_LOGE(context, "x rank too large"), return ge::GRAPH_FAILED);

    int64_t xNumel = 1;
    for (int64_t d = 0; d < rank; ++d) {
        const int64_t N = xShape.GetDim(static_cast<size_t>(d));
        OP_CHECK_IF(N < 0, OP_LOGE(context, "x has unknown dim"), return ge::GRAPH_FAILED);
        tiling->xDims[d] = N;
        tiling->outDims[d] = 0;
        if (N > 0) {
            xNumel *= N;
            OP_CHECK_IF(xNumel > PADV3_XNUMEL_MAX, OP_LOGE(context, "x numel too large"),
                        return ge::GRAPH_FAILED);
        }
    }

    const gert::CompileTimeTensorDesc* xDesc = context->GetInputDesc(0);
    OP_CHECK_NULL_WITH_CONTEXT(context, xDesc);
    const ge::DataType dtX = xDesc->GetDataType();
    OP_CHECK_IF(dtX != ge::DT_FLOAT16 && dtX != ge::DT_FLOAT,
                OP_LOGE(context, "x dtype must be fp16/fp32"), return ge::GRAPH_FAILED);

    const int64_t elemSize = (dtX == ge::DT_FLOAT16) ? 2 : 4;
    const int64_t alignElem = (32 / elemSize > 0) ? (32 / elemSize) : 1;   /* 32B / 元素 */

    /* ---------- 2. paddings shape / dtype（只校验元素数，不读值） ---------- */
    const gert::StorageShape* ps = context->GetInputShape(1);
    OP_CHECK_NULL_WITH_CONTEXT(context, ps);
    const gert::Shape& pShape = ps->GetStorageShape();
    int64_t pNum = 0;
    if (pShape.GetDimNum() == 0) {
        /* rank0 的 [] 视为空 paddings；rank>0 时标量 paddings 非法（1 != 2R） */
        pNum = (rank == 0) ? 0 : 1;
    } else {
        pNum = NumelOfShape(pShape);
        OP_CHECK_IF(pNum < 0, OP_LOGE(context, "paddings has unknown dim"), return ge::GRAPH_FAILED);
    }
    OP_CHECK_IF(pNum != 2 * rank, OP_LOGE(context, "paddings numel must be 2*rank"),
                return ge::GRAPH_FAILED);

    const gert::CompileTimeTensorDesc* pDesc = context->GetInputDesc(1);
    OP_CHECK_NULL_WITH_CONTEXT(context, pDesc);
    const ge::DataType dtP = pDesc->GetDataType();
    OP_CHECK_IF(dtP != ge::DT_INT32 && dtP != ge::DT_INT64,
                OP_LOGE(context, "paddings dtype must be int32/int64"), return ge::GRAPH_FAILED);

    /* ---------- 3. attr（null -> def.cpp 默认值） ---------- */
    int64_t mode = 2;
    int64_t contiguous = 1;
    const gert::RuntimeAttrs* attrs = context->GetAttrs();
    if (attrs != nullptr) {
        const char* modeStr = attrs->GetStr(0);
        mode = MapMode(modeStr);
        OP_CHECK_IF(mode < 0, OP_LOGE(context, "unsupported mode"), return ge::GRAPH_FAILED);
        const bool* pc = attrs->GetAttrPointer<bool>(1);
        if (pc != nullptr) {
            contiguous = (*pc) ? 1 : 0;
        }
    }

    /* ---------- 4. 输出 shape（可选；默认关闭，见 PADV3_TILING_USE_OUT_SHAPE） ---------- */
    bool outKnown = false;
    int64_t totalOut = 0;
#if PADV3_TILING_USE_OUT_SHAPE
    const gert::StorageShape* so = context->GetOutputShape(0);
    if (so != nullptr) {
        const gert::Shape& outShape = so->GetStorageShape();
        if (static_cast<int64_t>(outShape.GetDimNum()) == rank) {
            outKnown = true;
            totalOut = 1;
            for (int64_t d = 0; d < rank; ++d) {
                const int64_t v = outShape.GetDim(static_cast<size_t>(d));
                if (v < 0) {
                    outKnown = false;
                    break;
                }
                tiling->outDims[d] = v;
                totalOut *= v;   /* 任一维为 0 -> totalOut=0（空输出） */
            }
            if (outKnown && totalOut > PADV3_XNUMEL_MAX) {
                outKnown = false;
            }
        }
    }
#endif
    if (!outKnown) {
        for (int64_t d = 0; d < rank && d < PADV3GRAD_MAX_RANK; ++d) {
            tiling->outDims[d] = 0;
        }
    }

    /* ---------- 5. 分核：按工作量 x.numel ---------- */
    int64_t usedCore = CeilDivI(xNumel, MIN_WORK_PER_CORE);
    if (usedCore < 1) {
        usedCore = 1;
    }
    if (usedCore > coreNum) {
        usedCore = coreNum;
    }
    int64_t blockFactor = 0;
    if (outKnown && totalOut > 0) {
        /* 每核输出起点必须 32B 字节对齐：blockFactor 向上对齐到 32/sizeof(T) 个元素 */
        blockFactor = CeilDivI(totalOut, usedCore);
        blockFactor = ((blockFactor + alignElem - 1) / alignElem) * alignElem;
        if (blockFactor < alignElem) {
            blockFactor = alignElem;
        }
        const int64_t coresNeeded = CeilDivI(totalOut, blockFactor);
        if (coresNeeded >= 1 && coresNeeded < usedCore) {
            usedCore = coresNeeded;
        }
    }

    /* ---------- 6. ubFactor ---------- */
    const int64_t ubFactor = CalcUbFactor(ubSize, elemSize);

    /* ---------- 7. 写 tiling ---------- */
    tiling->totalNum = (outKnown && totalOut > 0) ? totalOut : 0;
    tiling->blockFactor = blockFactor;
    tiling->ubFactor = ubFactor;
    tiling->rank = rank;
    tiling->mode = mode;
    tiling->paddingsContiguous = contiguous;
    tiling->paddingsInt64 = (dtP == ge::DT_INT64) ? 1 : 0;
    tiling->coreNum = usedCore;
    tiling->dtypeCode = (dtX == ge::DT_FLOAT16) ? 0 : 1;

    context->SetBlockDim(static_cast<uint32_t>(usedCore));

    uint64_t tilingKey;
    if (dtX == ge::DT_FLOAT16) {
        tilingKey = GET_TPL_TILING_KEY(PADV3GRAD_TPL_SCH_MODE_0);
    } else {
        tilingKey = GET_TPL_TILING_KEY(PADV3GRAD_TPL_SCH_MODE_1);
    }
    context->SetTilingKey(tilingKey);
    return ge::GRAPH_SUCCESS;
}

static ge::graphStatus TilingParseForPadV3Grad([[maybe_unused]] gert::TilingParseContext* context)
{
    return ge::GRAPH_SUCCESS;
}

struct PadV3GradCompileInfo {};

IMPL_OP_OPTILING(PadV3Grad).Tiling(PadV3GradTilingFunc).TilingParse<PadV3GradCompileInfo>(TilingParseForPadV3Grad);

} // namespace optiling

/*!
 * \file pad_v3_grad.cpp
 * \brief PadV3Grad 算子 kernel 入口
 */

#include "pad_v3_grad.h"

enum class PadV3GradTilingKey : uint32_t
{
    TILING_KEY_PADV3GRAD_MODE_0 = 0,
    TILING_KEY_PADV3GRAD_MODE_1 = 1,
};

template <uint32_t schMode>
__global__ __aicore__ void pad_v3_grad(GM_ADDR x, GM_ADDR paddings, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    REGISTER_TILING_DEFAULT(PadV3GradTilingData);
    GET_TILING_DATA_WITH_STRUCT(PadV3GradTilingData, tilingData, tiling);
    if constexpr (schMode == static_cast<uint32_t>(PadV3GradTilingKey::TILING_KEY_PADV3GRAD_MODE_0)) {
        NsPadV3Grad::PadV3Grad<half> op;
        op.Init(x, paddings, y, &tilingData);
        op.Process();
    }
    if constexpr (schMode == static_cast<uint32_t>(PadV3GradTilingKey::TILING_KEY_PADV3GRAD_MODE_1)) {
        NsPadV3Grad::PadV3Grad<float> op;
        op.Init(x, paddings, y, &tilingData);
        op.Process();
    }
}

/*!
 * \file pad_v3_grad.h
 * \brief PadV3Grad kernel 实现（S0 Rev.2）
 *
 * 语义（reference.py）：
 *   - x 是 PadV3 前向输出（padded），y 是原张量梯度；
 *   - 非 constant：y[i_vec] = Σ_{j: pad_index(j_d) == i_d, ∀d} x[j_vec + front_vec]
 *     其中 j_d 是算术坐标，j_d ∈ [-front_d, n_d + back_d)，物理下标 = j_d + front_d；
 *   - constant：y[i_vec] = x[i_vec + front_vec]（中间块，无累加）。
 *
 * 关键点：
 *   1. 有符号 front/back：每个预像组都与 [-front, n+back) 求交；交集为空 -> 该输出为 0。
 *   2. 每个核独占输出扁平区间 [start_, end_)：无 race、无需清零、无 workspace。
 *   3. 精度：Neumaier（hi/lo）补偿 + 非有限值旁路（位模式判断，Inf+Inf 不会被算成 NaN）。
 *   4. 本核输出区间全覆盖写入；不 clamp、不部分写。
 *   5. constant + 负 pad：reference 自身返回的 shape 与声明不符（无合法 golden），
 *      kernel 对本核区间全写 0（确定性、全覆盖）。
 */
#ifndef PADV3GRAD_H
#define PADV3GRAD_H

#include "kernel_operator.h"
#include "kernel_tiling/kernel_tiling.h"
#include "pad_v3_grad_tiling_data.h"
#include "pad_v3_grad_tiling_key.h"

namespace NsPadV3Grad {
using namespace AscendC;

constexpr int32_t BUFFER_NUM = 1;
constexpr int32_t PAD_MAX_RANK = PADV3GRAD_MAX_RANK;
constexpr int32_t PAD_MAX_GROUPS = 2;

union FloatUint32 {
    float f;
    uint32_t u;
};

template <typename T> struct PadConvert;
template <> struct PadConvert<float> {
    __aicore__ static inline float ToFloat(float v) { return v; }
    __aicore__ static inline float FromFloat(float v) { return v; }
};
template <> struct PadConvert<half> {
    __aicore__ static inline float ToFloat(half v) { return static_cast<float>(v); }
    __aicore__ static inline half FromFloat(float v) { return static_cast<half>(v); }
};

/* fast-math 安全的有限性判断：指数位全 1 -> Inf/NaN */
__aicore__ inline bool PadIsFinite(float v)
{
    FloatUint32 c;
    c.f = v;
    return (c.u & 0x7f800000u) != 0x7f800000u;
}

/* Neumaier（补偿求和）。
 * 非有限旁路：
 *   - 任一操作数非有限（Inf/NaN）-> 直接相加、comp=0，保证 Inf+(-Inf)=NaN、
 *     Inf+有限=Inf、NaN 传播；
 *   - 两个有限数相加**溢出到 ±Inf**（如 3e38+3e38）-> 直接返回 t，comp=0。
 *     否则补偿项 (hi-t)+v 会算出 -Inf，最终 hi+comp = Inf+(-Inf) = NaN，
 *     而 reference(fp64->fp32) 是 Inf。
 */
__aicore__ inline float PadAccStep(float hi, float& comp, float v)
{
    if (PadIsFinite(hi) && PadIsFinite(v)) {
        const float t = hi + v;
        if (PadIsFinite(t)) {
            const float ah = (hi < 0.0f) ? -hi : hi;
            const float av = (v < 0.0f) ? -v : v;
            if (ah >= av) {
                comp += (hi - t) + v;
            } else {
                comp += (v - t) + hi;
            }
            return t;
        }
        comp = 0.0f;
        return t;   /* ±Inf（fp32 中间和溢出；与 reference 的该次加法一致） */
    }
    comp = 0.0f;
    return hi + v;
}

/* C++ 整除是截断，负数时需要 floor-mod（审计 P3） */
__aicore__ inline int64_t PadFloorDiv(int64_t a, int64_t b)
{
    int64_t q = a / b;
    int64_t r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) {
        q -= 1;
    }
    return q;
}

__aicore__ inline int64_t PadCeilDiv(int64_t a, int64_t b)
{
    return -PadFloorDiv(-a, b);
}

template <typename T>
class PadV3Grad {
public:
    __aicore__ inline PadV3Grad() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR paddings, GM_ADDR y,
                                const PadV3GradTilingData* tilingData);
    __aicore__ inline void Process();

private:
    __aicore__ inline bool BuildGroups(int64_t flat);
    __aicore__ inline bool BuildGroupsFromDec();
    __aicore__ inline bool UpdateDimGroups(int64_t d);
    __aicore__ inline void AddGroup(int64_t slot, int64_t r, int64_t step, int64_t jlo, int64_t jhi);
    __aicore__ inline int64_t GroupJ(int64_t d, int64_t k) const;
    __aicore__ inline void ComputeChunk(int64_t chunkStart, int64_t chunkLen);
    __aicore__ inline void ComputeConstantChunk(int64_t chunkStart, int64_t chunkLen);
    __aicore__ inline void CopyOutChunk(int64_t chunkStart, int64_t chunkLen);

    TPipe pipe_;
    TBuf<TPosition::VECCALC> outBuf_;
    LocalTensor<T> outLocal_;
    GlobalTensor<T> xGm_;
    GlobalTensor<T> yGm_;
    GlobalTensor<int32_t> padGm32_;
    GlobalTensor<int64_t> padGm64_;

    int64_t rank_ = 0;
    int64_t mode_ = 2;
    int64_t contiguous_ = 1;
    int64_t useInt64Pad_ = 0;
    int64_t coreNum_ = 1;
    int64_t ubFactor_ = 0;
    int64_t xDims_[PAD_MAX_RANK] = {0};
    int64_t outDims_[PAD_MAX_RANK] = {0};
    int64_t front_[PAD_MAX_RANK] = {0};
    int64_t back_[PAD_MAX_RANK] = {0};
    int64_t strides_[PAD_MAX_RANK] = {0};
    int64_t total_ = 0;
    int64_t start_ = 0;
    int64_t end_ = 0;
    int64_t hasNegPad_ = 0;

    /* 每个输出元素的预像组（成员数组，避免 __aicore__ 内大栈数组） */
    int64_t iDec_[PAD_MAX_RANK] = {0};
    int64_t gr_[PAD_MAX_RANK * PAD_MAX_GROUPS] = {0};
    int64_t gs_[PAD_MAX_RANK * PAD_MAX_GROUPS] = {0};
    int64_t gt0_[PAD_MAX_RANK * PAD_MAX_GROUPS] = {0};
    int64_t gcnt_[PAD_MAX_RANK * PAD_MAX_GROUPS] = {0};
    int64_t dimCnt_[PAD_MAX_RANK] = {0};
    /* exp14_validcnt：dimCnt_[d] <= 0 的维度个数。
     * 原来每个元素都要全 rank 重扫一遍算 elemOk（诊断实测：ComputeChunk 里
     * 「簿记」占 48% 的耗时，gather 只占 19%）。改成在 UpdateDimGroups 里增量维护。 */
    int64_t badDims_ = 0;
    int64_t pos_[PAD_MAX_RANK] = {0};
};

template <typename T>
__aicore__ inline void PadV3Grad<T>::Init(GM_ADDR x, GM_ADDR paddings, GM_ADDR y,
                                          const PadV3GradTilingData* tilingData)
{
    if (tilingData == nullptr || x == nullptr || y == nullptr) {
        return;
    }
    rank_ = tilingData->rank;
    if (rank_ < 0 || rank_ > PAD_MAX_RANK) {
        return;
    }
    coreNum_ = tilingData->coreNum;
    if (coreNum_ < 1 || coreNum_ > 1024) {
        return;
    }
    ubFactor_ = tilingData->ubFactor;
    if (ubFactor_ < 1 || ubFactor_ > PADV3_UB_MAX) {
        return;
    }
    mode_ = tilingData->mode;
    if (mode_ < 0 || mode_ > 4) {
        return;
    }
    contiguous_ = (tilingData->paddingsContiguous != 0) ? 1 : 0;
    useInt64Pad_ = (tilingData->paddingsInt64 != 0) ? 1 : 0;

    int64_t xNumel = 1;
    for (int64_t d = 0; d < rank_; ++d) {
        const int64_t N = tilingData->xDims[d];
        if (N < 0) {
            return;
        }
        xDims_[d] = N;
        outDims_[d] = 0;
        front_[d] = 0;
        back_[d] = 0;
        strides_[d] = 1;
        if (N > 0) {
            xNumel *= N;
            if (xNumel > PADV3_XNUMEL_MAX) {
                return;
            }
        }
    }

    /* ---- 从 GM 读 paddings（2R 个 int32/int64）---- */
    const int64_t padCount = 2 * rank_;
    if (padCount > 0) {
        if (paddings == nullptr) {
            return;
        }
        if (useInt64Pad_ != 0) {
            padGm64_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t*>(paddings), padCount);
        } else {
            padGm32_.SetGlobalBuffer(reinterpret_cast<__gm__ int32_t*>(paddings), padCount);
        }
    }
    for (int64_t d = 0; d < rank_; ++d) {
        int64_t f = 0;
        int64_t b = 0;
        if (padCount > 0) {
            const int64_t i0 = (contiguous_ != 0) ? (2 * d) : d;
            const int64_t i1 = (contiguous_ != 0) ? (2 * d + 1) : (rank_ + d);
            if (useInt64Pad_ != 0) {
                f = padGm64_.GetValue(static_cast<uint32_t>(i0));
                b = padGm64_.GetValue(static_cast<uint32_t>(i1));
            } else {
                f = static_cast<int64_t>(padGm32_.GetValue(static_cast<uint32_t>(i0)));
                b = static_cast<int64_t>(padGm32_.GetValue(static_cast<uint32_t>(i1)));
            }
        }
        /* 防 int64 溢出：paddings 是外部输入，限制在 [-(2^40), 2^40] */
        if (f < -PADV3_XNUMEL_MAX || f > PADV3_XNUMEL_MAX ||
            b < -PADV3_XNUMEL_MAX || b > PADV3_XNUMEL_MAX) {
            return;
        }
        front_[d] = f;
        back_[d] = b;
        if (f < 0 || b < 0) {
            hasNegPad_ = 1;
        }
        const int64_t n = xDims_[d] - f - b;
        if (n < 0) {
            return;   /* 非法（front+back > N）：无合法 golden */
        }
        outDims_[d] = n;
    }

    /* ---- x 的行主序 stride ---- */
    for (int64_t d = rank_ - 1; d >= 0; --d) {
        int64_t s = 1;
        for (int64_t k = d + 1; k < rank_; ++k) {
            s *= xDims_[k];
        }
        strides_[d] = s;
    }

    /* ---- 输出总数（rank0 -> 1）---- */
    total_ = 1;
    for (int64_t d = 0; d < rank_; ++d) {
        if (outDims_[d] <= 0 || outDims_[d] > PADV3_XNUMEL_MAX) {
            total_ = 0;
            break;
        }
        total_ *= outDims_[d];
        if (total_ > PADV3_XNUMEL_MAX) {
            total_ = 0;
            break;
        }
    }
    if (total_ <= 0) {
        return;   /* 空输出：不启动计算 */
    }

    /* ---- 分核：以 kernel 自己算出的 total_ 为准 ----
     * 每核起点必须是 32B 字节对齐：blockFactor 向上对齐到 32/sizeof(T) 个元素。
     * 这样 start_ = coreId*bf 与 chunkStart = start_ + k*ubFactor_ 都是 32B 对齐，
     * DataCopyPad 的目的 GM 起点不再依赖“非 32B 对齐 GM 起始”。
     */
    const int64_t alignElem = static_cast<int64_t>(32 / sizeof(T));
    if (alignElem < 1 || (ubFactor_ % alignElem) != 0) {
        return;
    }
    const int64_t coreId = static_cast<int64_t>(GetBlockIdx());
    if (coreId < 0 || coreId >= coreNum_) {
        return;
    }
    int64_t bf = 0;
    if (tilingData->totalNum > 0 && tilingData->totalNum == total_ && tilingData->blockFactor > 0) {
        bf = tilingData->blockFactor;
    } else {
        bf = (total_ + coreNum_ - 1) / coreNum_;
    }
    if (bf <= 0) {
        return;
    }
    bf = ((bf + alignElem - 1) / alignElem) * alignElem;   /* 幂等：tiling 已对齐时不变 */
    start_ = coreId * bf;
    end_ = start_ + bf;
    if (end_ > total_) {
        end_ = total_;
    }
    if (start_ >= end_) {
        return;
    }

    xGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x), (xNumel > 0) ? xNumel : 1);
    yGm_.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y), total_);

    int64_t outBytes = ubFactor_ * static_cast<int64_t>(sizeof(T));
    if (outBytes < 32) {
        outBytes = 32;
    }
    pipe_.InitBuffer(outBuf_, outBytes);
    outLocal_ = outBuf_.Get<T>();
}

template <typename T>
__aicore__ inline void PadV3Grad<T>::AddGroup(int64_t slot, int64_t r, int64_t step,
                                              int64_t jlo, int64_t jhi)
{
    /* j = r + t*step，t ∈ [t0, t1] */
    const int64_t t0 = PadCeilDiv(jlo - r, step);
    const int64_t t1 = PadCeilDiv(jhi - r, step) - 1;
    int64_t cnt = t1 - t0 + 1;
    if (cnt < 0) {
        cnt = 0;
    }
    gr_[slot] = r;
    gs_[slot] = step;
    gt0_[slot] = t0;
    gcnt_[slot] = cnt;
}

template <typename T>
__aicore__ inline bool PadV3Grad<T>::BuildGroups(int64_t flat)
{
    /* 解码输出多下标 */
    int64_t rem = flat;
    for (int64_t d = rank_ - 1; d >= 0; --d) {
        const int64_t n = outDims_[d];
        if (n <= 0) {
            return false;
        }
        iDec_[d] = rem % n;
        rem /= n;
    }
    return BuildGroupsFromDec();
}

/* exp7_odometer：直接使用已维护的 iDec_（ComputeChunk 增量推进），跳过每元素的
 * rank 层 div/mod。语义与 BuildGroups(flat) 完全一致。 */
template <typename T>
__aicore__ inline bool PadV3Grad<T>::BuildGroupsFromDec()
{
    for (int64_t d = 0; d < rank_; ++d) {
        UpdateDimGroups(d);
    }
    for (int64_t d = 0; d < rank_; ++d) {
        if (dimCnt_[d] <= 0) {
            return false;
        }
    }
    return true;
}

/* exp8_incgroup：只重算 index 发生变化的维度。语义与逐元素全量 BuildGroupsFromDec 一致
 * （同一个函数体，只是把「哪些维度变了」交给调用方）。 */
template <typename T>
__aicore__ inline bool PadV3Grad<T>::UpdateDimGroups(int64_t d)
{
    {
        const int64_t n = outDims_[d];
        if (n <= 0) {
            if (dimCnt_[d] > 0) {
                ++badDims_;
            }
            dimCnt_[d] = 0;   /* 防御：Init 已保证 >0；置 0 让 elemOk 判为无效 */
            return false;
        }
        const int64_t jlo = -front_[d];
        const int64_t jhi = n + back_[d];
        const int64_t s0 = 2 * d;
        gcnt_[s0] = 0;
        gcnt_[s0 + 1] = 0;

        /* exp15_identfast：最内维每元素都要跑下面的分支树 + 两次 AddGroup(含取模)，
         * 实测「每元素簿记」占 06 总耗时的 48%。中间位置的映射是恒等单点，
         * 直接写掉分组即可（表示法与 mode1 的恒等分支完全一致，GroupJ 结果相同）。
         * 判据由 numpy 模型穷举验证：误判 0 例；守卫之外一律走原路径。 */
        if (d == rank_ - 1 && mode_ >= 2 && n >= 8 && front_[d] >= 0 && back_[d] >= 0 &&
            front_[d] + back_[d] + 4 <= n) {
            const int64_t ivF = iDec_[d];
            bool idFast;
            if (mode_ == 2) {
                idFast = (ivF == 0 || ivF >= front_[d] + 1) &&
                         (ivF == n - 1 || ivF <= n - 2 - back_[d]);
            } else {
                idFast = (ivF >= front_[d]) && (ivF <= n - 1 - back_[d]);
            }
            if (idFast) {
                gr_[s0] = 0;
                gs_[s0] = 1;
                gt0_[s0] = ivF;
                gcnt_[s0] = 1;
                const int64_t oldCntF = dimCnt_[d];
                dimCnt_[d] = 1;
                if ((dimCnt_[d] <= 0) != (oldCntF <= 0)) {
                    badDims_ += (dimCnt_[d] <= 0) ? 1 : -1;
                }
                return true;
            }
        }

        if (n == 1) {
            /* 所有 padded 位置都映射到 0（含 edge；reflect/symmetric/circular 同） */
            if (jhi > jlo) {
                gr_[s0] = 0;
                gs_[s0] = 1;
                gt0_[s0] = jlo;
                gcnt_[s0] = jhi - jlo;
            }
        } else if (mode_ == 1) {
            /* edge / replicate：端点是连续区间，中间是单点；全部与 [jlo, jhi) 求交 */
            const int64_t iv = iDec_[d];
            if (iv == 0) {
                const int64_t t1 = (jhi - 1 < 0) ? (jhi - 1) : 0;
                if (t1 >= jlo) {
                    gr_[s0] = 0;
                    gs_[s0] = 1;
                    gt0_[s0] = jlo;
                    gcnt_[s0] = t1 - jlo + 1;
                }
            } else if (iv == n - 1) {
                const int64_t t0 = (jlo > n - 1) ? jlo : (n - 1);
                if (jhi - 1 >= t0) {
                    gr_[s0] = 0;
                    gs_[s0] = 1;
                    gt0_[s0] = t0;
                    gcnt_[s0] = jhi - t0;
                }
            } else {
                if (iv >= jlo && iv < jhi) {
                    gr_[s0] = 0;
                    gs_[s0] = 1;
                    gt0_[s0] = iv;
                    gcnt_[s0] = 1;
                }
            }
        } else {
            const int64_t P = (mode_ == 2) ? (2 * (n - 1)) : ((mode_ == 3) ? (2 * n) : n);
            AddGroup(s0, iDec_[d] % P, P, jlo, jhi);
            if (mode_ == 2) {
                /* reflect 的两组在 i=0 / i=n-1 重合，需去重 */
                if (iDec_[d] != 0 && iDec_[d] != n - 1) {
                    AddGroup(s0 + 1, (P - iDec_[d]) % P, P, jlo, jhi);
                }
            } else if (mode_ == 3) {
                AddGroup(s0 + 1, (2 * n - 1 - iDec_[d]) % P, P, jlo, jhi);
            }
        }
        {
            const int64_t oldCnt = dimCnt_[d];
            dimCnt_[d] = gcnt_[s0] + gcnt_[s0 + 1];
            if ((dimCnt_[d] <= 0) != (oldCnt <= 0)) {
                badDims_ += (dimCnt_[d] <= 0) ? 1 : -1;
            }
        }
        return dimCnt_[d] > 0;
    }
}

template <typename T>
__aicore__ inline int64_t PadV3Grad<T>::GroupJ(int64_t d, int64_t k) const
{
    const int64_t s0 = 2 * d;
    if (k < gcnt_[s0]) {
        return gr_[s0] + (gt0_[s0] + k) * gs_[s0];
    }
    const int64_t kk = k - gcnt_[s0];
    return gr_[s0 + 1] + (gt0_[s0 + 1] + kk) * gs_[s0 + 1];
}

template <typename T>
__aicore__ inline void PadV3Grad<T>::ComputeChunk(int64_t chunkStart, int64_t chunkLen)
{
    /* exp7_odometer：chunkStart 的多下标只解码一次，之后逐元素 +1 进位。
     * 旧实现对每个元素重做 rank 层 div/mod（`rem % n` + `rem /= n`）。 */
    int64_t remDec = chunkStart;
    for (int64_t d = rank_ - 1; d >= 0; --d) {
        const int64_t n = outDims_[d];
        iDec_[d] = (n > 0) ? (remDec % n) : 0;
        remDec = (n > 0) ? (remDec / n) : 0;
    }
    /* exp8_incgroup：chunk 起点做一次全量 group 构建；之后每次 index +1 只重算变化的维度。 */
    badDims_ = 0;
    for (int64_t d = 0; d < rank_; ++d) {
        dimCnt_[d] = 1;   /* 占位 >0，让 badDims_ 的增量维护从 0 起算 */
    }
    for (int64_t d = 0; d < rank_; ++d) {
        UpdateDimGroups(d);
    }
    bool elemOk = (badDims_ == 0);
    for (int64_t k = 0; k < chunkLen; ++k) {
        float val = 0.0f;
        if (elemOk) {
            for (int64_t d = 0; d < rank_; ++d) {
                pos_[d] = 0;
            }
            float hi = 0.0f;
            float comp = 0.0f;
            bool done = false;
            while (!done) {
                int64_t src = 0;
                for (int64_t d = 0; d < rank_; ++d) {
                    src += (GroupJ(d, pos_[d]) + front_[d]) * strides_[d];
                }
                const float v = PadConvert<T>::ToFloat(xGm_.GetValue(static_cast<uint64_t>(src)));
                hi = PadAccStep(hi, comp, v);

                int64_t dd = rank_ - 1;
                while (dd >= 0) {
                    pos_[dd] += 1;
                    if (pos_[dd] < dimCnt_[dd]) {
                        break;
                    }
                    pos_[dd] = 0;
                    dd -= 1;
                }
                if (dd < 0) {
                    done = true;
                }
            }
            val = hi + comp;
        }
        outLocal_.SetValue(k, PadConvert<T>::FromFloat(val));
        if (k + 1 < chunkLen) {
            /* 多下标 +1；只有发生变化的维度需要重算 group（进位链上每一维都变了）。 */
            for (int64_t d = rank_ - 1; d >= 0; --d) {
                ++iDec_[d];
                if (iDec_[d] < outDims_[d]) {
                    UpdateDimGroups(d);
                    break;
                }
                iDec_[d] = 0;
                UpdateDimGroups(d);
            }
            elemOk = (badDims_ == 0);
        }
    }
}

template <typename T>
__aicore__ inline void PadV3Grad<T>::ComputeConstantChunk(int64_t chunkStart, int64_t chunkLen)
{
    /* exp9_constodo：mode 0 是平移拷贝 dx[i] = dy[i+front]。
     * 旧实现每个元素重做 rank 层 div/mod 与 rank 次乘加；这里解码一次、
     * 之后最内维 +1（stride==1）时 src 直接 +1，只在进位时按 iDec_ 重算 src。 */
    if (hasNegPad_ != 0) {
        for (int64_t k = 0; k < chunkLen; ++k) {
            outLocal_.SetValue(k, PadConvert<T>::FromFloat(0.0f));
        }
        return;
    }
    for (int64_t d = 0; d < rank_; ++d) {
        iDec_[d] = 0;
    }
    int64_t rem = chunkStart;
    for (int64_t d = rank_ - 1; d >= 0; --d) {
        const int64_t n = outDims_[d];
        iDec_[d] = (n > 0) ? (rem % n) : 0;
        rem = (n > 0) ? (rem / n) : 0;
    }
    int64_t src = 0;
    for (int64_t d = 0; d < rank_; ++d) {
        src += (iDec_[d] + front_[d]) * strides_[d];
    }
    for (int64_t k = 0; k < chunkLen; ++k) {
        outLocal_.SetValue(k,
            PadConvert<T>::FromFloat(PadConvert<T>::ToFloat(xGm_.GetValue(static_cast<uint64_t>(src)))));
        if (k + 1 < chunkLen && rank_ > 0) {
            ++iDec_[rank_ - 1];
            if (iDec_[rank_ - 1] < outDims_[rank_ - 1]) {
                src += strides_[rank_ - 1];   /* 最内维 stride 恒为 1 */
            } else {
                iDec_[rank_ - 1] = 0;
                for (int64_t d = rank_ - 2; d >= 0; --d) {
                    ++iDec_[d];
                    if (iDec_[d] < outDims_[d]) {
                        break;
                    }
                    iDec_[d] = 0;
                }
                src = 0;
                for (int64_t d = 0; d < rank_; ++d) {
                    src += (iDec_[d] + front_[d]) * strides_[d];
                }
            }
        }
    }
}

template <typename T>
__aicore__ inline void PadV3Grad<T>::CopyOutChunk(int64_t chunkStart, int64_t chunkLen)
{
    PipeBarrier<PIPE_ALL>();
    DataCopyExtParams p;
    p.blockCount = 1;
    p.blockLen = static_cast<uint32_t>(chunkLen * static_cast<int64_t>(sizeof(T)));
    p.srcStride = 0;
    p.dstStride = 0;
    p.rsv = 0;
    DataCopyPad(yGm_[chunkStart], outLocal_, p);
    PipeBarrier<PIPE_ALL>();
}

template <typename T>
__aicore__ inline void PadV3Grad<T>::Process()
{
    if (start_ >= end_) {
        return;
    }
    for (int64_t chunkStart = start_; chunkStart < end_; chunkStart += ubFactor_) {
        int64_t chunkLen = end_ - chunkStart;
        if (chunkLen > ubFactor_) {
            chunkLen = ubFactor_;
        }
        if (mode_ == 0) {
            ComputeConstantChunk(chunkStart, chunkLen);
        } else {
            ComputeChunk(chunkStart, chunkLen);
        }
        CopyOutChunk(chunkStart, chunkLen);
    }
}

